#!/bin/bash
# Benchmark of the control API (release vs debug builds) on an ISOLATED, SYNTHETIC dataset. Never run against real services.
#   scripts/bench_release.sh <api-release> <api-debug> <hickory-dns-release> <httpload> <pg-container> <outdir>
# Dataset (synthetic, generated by SQL): 5,007 zones x 8 records (40k records) in 100 tenants + admin zones, 200 zones with 14 days of
# 5-minute analytics samples plus record-type and country breakdowns (~8M rows). Output: results.json, plans.txt, env.txt.
set -u
APIR=${1:?}; APID=${2:?}; DNSR=${3:?}; LOAD=${4:?}; PGC=${5:?}; OUT=${6:?}
mkdir -p "$OUT"; W=$(mktemp -d); chmod 755 "$W"; DB=bench_db; PORT=18140; DNSP=5420; API_PID=""; DNS_PID=""
cleanup() { kill $API_PID $DNS_PID 2>/dev/null; rm -rf "$W"; }; trap cleanup EXIT
psqlq() { docker exec -i "$PGC" psql -U postgres -d $DB -qtA "$@"; }
[ -z "${BENCH_REUSE:-}" ] && docker exec "$PGC" psql -U postgres -qc "DROP DATABASE IF EXISTS $DB WITH (FORCE)" -c "CREATE DATABASE $DB" >/dev/null
export DATABASE_URL="postgres://postgres:pw@127.0.0.1:55432/$DB" JWT_SECRET=bench-secret-0123456789abcdef0123456789 ADMIN_USERNAME=admin ADMIN_PASSWORD='Bench-Admin-Pw-9911' \
  ALLOWED_ORIGINS=http://127.0.0.1:5173 PUBLIC_NAMESERVERS=ns1.example.test.,ns2.example.test. LOGIN_RATE_PER_IP=1000000 BIND_ADDR=127.0.0.1:$PORT LISTEN_ADDRS_IPV4=127.0.0.1 \
  DNS_LOOKUP_RATE_PER_MIN=100000000 DNS_LOOKUP_RESOLVERS=127.0.0.1:$DNSP ANALYTICS_SAMPLE_SECS=0 PROMETHEUS_LISTEN_ADDR=127.0.0.1:19141 DB_POOL_SIZE=8
ticks=$(getconf CLK_TCK)
j() { python3 -c "import sys,json; d=json.load(sys.stdin); print($1)"; }
STARTUP_MS=0
start_api() { # binary; sets API_PID and STARTUP_MS in THIS shell (never call it inside $(...))
  if ss -ltn | grep -q ":$PORT "; then echo "port $PORT is already in use: refusing to benchmark a foreign process" >&2; exit 3; fi
  local t0=$(date +%s%N); mkdir -p "$W/dns"; HICKORY_DNS_DIR="$W/dns" "$1" >"$W/api.log" 2>&1 & API_PID=$!
  for i in $(seq 1 12000); do curl -sf http://127.0.0.1:$PORT/health >/dev/null 2>&1 && break; sleep 0.05; done
  STARTUP_MS=$(( ($(date +%s%N) - t0) / 1000000 )); }
stop_api() { kill $API_PID 2>/dev/null; wait $API_PID 2>/dev/null; for i in $(seq 1 50); do ss -ltn | grep -q ":$PORT " || break; sleep 0.1; done; }
rss() { awk '/VmRSS/{print $2}' /proc/$API_PID/status; }; hwm() { awk '/VmHWM/{print $2}' /proc/$API_PID/status; }
cpu() { awk '{print $14+$15}' /proc/$API_PID/stat; }

# ---- environment record
{ echo "date: $(date -u +%FT%TZ)"; echo "kernel: $(uname -sr)"; echo "cpu: $(lscpu | awk -F: '/Model name/{gsub(/^ +/,"",$2);print $2; exit}') x$(nproc)"; echo "memory: $(free -m | awk '/Mem:/{print $2" MB"}')"
  echo "rustc: $(rustc --version)"; echo "postgres: $(psqlq -c 'select version()' | cut -c1-60)"; echo "release profile: opt-level=3 lto=true codegen-units=1 (crates/control_api/Cargo.toml)"; echo "debug profile: opt-level=0"
  echo "pool: DB_POOL_SIZE=8; load generator: scripts/httpload.rs on the same host (shares the 4 cores with API+PostgreSQL)"; } > "$OUT/env.txt"

if [ -z "${BENCH_REUSE:-}" ]; then   # BENCH_REUSE=1 re-uses the already seeded (and rolled-up) database
# ---- schema + seed (the first start of the release binary runs the migrations on the empty database)
start_api $APIR; echo "startup (empty DB, all migrations) release: $STARTUP_MS ms" | tee -a "$OUT/env.txt"; stop_api
start_api $APIR
TOK=$(curl -s -X POST http://127.0.0.1:$PORT/api/v1/auth/login -H 'content-type: application/json' -d '{"username":"admin","password":"Bench-Admin-Pw-9911"}' | j 'd["token"]')
curl -s -X POST http://127.0.0.1:$PORT/api/v1/users -H "authorization: Bearer $TOK" -H 'content-type: application/json' -d '{"username":"bench_alice","password":"Bench-Alice-Pw-1234","role":"editor"}' >/dev/null
ATOK=$(curl -s -X POST http://127.0.0.1:$PORT/api/v1/auth/login -H 'content-type: application/json' -d '{"username":"bench_alice","password":"Bench-Alice-Pw-1234"}' | j 'd["token"]')
for d in bench-alice-1 bench-alice-2 bench-alice-3 bench-alice-4 bench-alice-5; do curl -s -X POST http://127.0.0.1:$PORT/api/v1/zones -H "authorization: Bearer $ATOK" -H 'content-type: application/json' -d "{\"domain\":\"$d.example\",\"geodns_enabled\":false}" >/dev/null; done
curl -s -X POST http://127.0.0.1:$PORT/api/v1/zones -H "authorization: Bearer $TOK" -H 'content-type: application/json' -d '{"domain":"lookup.test","geodns_enabled":false}' > "$W/lz.json"
LZ=$(j 'd.get("id") or d["data"]["id"]' < "$W/lz.json"); curl -s -X POST http://127.0.0.1:$PORT/api/v1/zones/$LZ/records -H "authorization: Bearer $TOK" -H 'content-type: application/json' -d '{"name":"www","record_type":"A","value":"192.0.2.10","ttl":300}' >/dev/null
stop_api
echo "seeding synthetic data ..." >&2

psqlq <<'SQL'
INSERT INTO tenants (id, name) SELECT gen_random_uuid(), 'bench-tenant-' || g FROM generate_series(1,100) g;
INSERT INTO zones (id, domain, owner, tenant_id)
  SELECT gen_random_uuid(), 'bz' || g || '.example', NULL, (SELECT id FROM tenants WHERE name = 'bench-tenant-' || (g % 100 + 1)) FROM generate_series(1,5000) g;
INSERT INTO records (id, zone_id, name, record_type, value, ttl)
  SELECT gen_random_uuid(), z.id, 'h' || g, 'A', '192.0.2.' || (g % 250 + 1), 300 FROM zones z, generate_series(1,8) g WHERE z.domain LIKE 'bz%';
CREATE TEMP TABLE bz AS (SELECT domain, tenant_id FROM zones WHERE domain LIKE 'bz%' ORDER BY domain LIMIT 195) UNION ALL (SELECT domain, tenant_id FROM zones WHERE domain LIKE 'bench-alice-%');
INSERT INTO zone_query_samples (ts, tenant_id, domain, queries, failed)
  SELECT now() - make_interval(secs => s * 300), tenant_id, domain, 50 + (s % 17), s % 3 FROM bz, generate_series(0, 14*288) s;
INSERT INTO zone_qtype_samples (ts, tenant_id, domain, qtype, queries)
  SELECT now() - make_interval(secs => s * 300), tenant_id, domain, t, 10 + (s % 7) FROM bz, generate_series(0, 14*288) s, unnest(ARRAY['A','AAAA','MX','TXT']) t;
INSERT INTO zone_country_samples (ts, tenant_id, domain, country, queries)
  SELECT now() - make_interval(secs => s * 300), tenant_id, domain, c, 5 + (s % 5) FROM bz, generate_series(0, 14*288) s, unnest(ARRAY['US','DE','BR','ZZ-private','ZZ-unknown']) c;
INSERT INTO analytics_samples (ts, requests) SELECT now() - make_interval(secs => s * 300), 1000 + s % 50 FROM generate_series(0, 14*288) s;
ANALYZE;
SQL
{ echo "dataset: zones=$(psqlq -c 'select count(*) from zones') records=$(psqlq -c 'select count(*) from records') tenants=$(psqlq -c 'select count(*) from tenants')"
  echo "analytics rows: zone_query_samples=$(psqlq -c 'select count(*) from zone_query_samples') qtype=$(psqlq -c 'select count(*) from zone_qtype_samples') country=$(psqlq -c 'select count(*) from zone_country_samples')"
  echo "database size: $(psqlq -c "select pg_size_pretty(pg_database_size('$DB'))")"; } | tee -a "$OUT/env.txt"

# ---- housekeeping as the leader would run it: hourly rollup of samples older than 48 h (measured)
t0=$(date +%s)
RUST_LOG=info ANALYTICS_SAMPLE_SECS=1 start_api $APIR
for i in $(seq 1 600); do grep -q "analytics rollup merged" "$W/api.log" && break; sleep 0.5; done
echo "rollup phase: $(( $(date +%s) - t0 )) s incl. start-up; $(grep -o 'analytics rollup merged [0-9]* rows' "$W/api.log" | head -1)" | tee -a "$OUT/env.txt"
stop_api
{ echo "analytics rows after rollup: zone_query_samples=$(psqlq -c 'select count(*) from zone_query_samples') qtype=$(psqlq -c 'select count(*) from zone_qtype_samples') country=$(psqlq -c 'select count(*) from zone_country_samples')"; echo "database size after rollup: $(psqlq -c "select pg_size_pretty(pg_database_size('$DB'))") (VACUUM not run)"; } | tee -a "$OUT/env.txt"
psqlq -c "ANALYZE" >/dev/null
fi

# ---- a real hickory-dns (release) as the lookup target
mkdir -p "$W/dnsd" "$W/dns"
cat > "$W/dns/zone.lookup.test" <<Z
lookup.test. 3600 IN SOA ns1.example.test. hostmaster.lookup.test. 2026010101 3600 900 604800 300
lookup.test. 3600 IN NS ns1.example.test.
www.lookup.test. 300 IN A 192.0.2.10
Z
chmod -R a+rX "$W"
cat > "$W/dnsd/named.toml" <<T
listen_addrs_ipv4 = ["127.0.0.1"]
prometheus_listen_addr = "127.0.0.1:19142"
[[zones]]
zone = "lookup.test"
zone_type = "Primary"
[[zones.stores]]
type = "file"
zone_path = "$W/dns/zone.lookup.test"
T
"$DNSR" -c "$W/dnsd/named.toml" -z "$W/dnsd" --port $DNSP >"$W/dnsd.log" 2>&1 & DNS_PID=$!

# ---- run one build
echo '{' > "$OUT/results.json"; first=1
run_build() { # label binary
  local label=$1 bin=$2
  start_api $bin; local up_ms=$STARTUP_MS; sleep 1
  local TOKA TOKU; TOKA=$(curl -s -X POST http://127.0.0.1:$PORT/api/v1/auth/login -H 'content-type: application/json' -d '{"username":"admin","password":"Bench-Admin-Pw-9911"}' | j 'd["token"]')
  TOKU=$(curl -s -X POST http://127.0.0.1:$PORT/api/v1/auth/login -H 'content-type: application/json' -d '{"username":"bench_alice","password":"Bench-Alice-Pw-1234"}' | j 'd["token"]')
  local idle_rss; idle_rss=$(rss)
  [ $first = 0 ] && echo ',' >> "$OUT/results.json"; first=0
  echo "\"$label\": {\"startup_ms\": $up_ms, \"rss_idle_kb\": $idle_rss, \"tests\": [" >> "$OUT/results.json"; local firsttest=1
  t() { # name conns secs METHOD path token [body]
    local name=$1 c=$2 secs=$3 m=$4 path=$5 tok=$6 body=${7:-}
    local c0 t0 c1 t1 res
    c0=$(cpu); t0=$(date +%s.%N)
    if [ -n "$body" ]; then res=$($LOAD 127.0.0.1:$PORT $m "$path" -c $c -d $secs -w 1 -H "Authorization: Bearer $tok" -b "$body"); else res=$($LOAD 127.0.0.1:$PORT $m "$path" -c $c -d $secs -w 1 -H "Authorization: Bearer $tok"); fi
    c1=$(cpu); t1=$(date +%s.%N)
    local cpupct; cpupct=$(python3 -c "print(round(($c1-$c0)/$ticks/($t1-$t0)*100,1))")
    [ $firsttest = 0 ] && echo ',' >> "$OUT/results.json"; firsttest=0
    echo "{\"name\":\"$name\",\"result\":$res,\"api_cpu_percent\":$cpupct,\"rss_kb\":$(rss)}" >> "$OUT/results.json"
    echo "$label $name c=$c: $(echo "$res" | j '"rps=%s p50=%s p95=%s p99=%s err=%s st=%s" % (d["rps"],d["p50_ms"],d["p95_ms"],d["p99_ms"],d["errors"],d["status"])') cpu=${cpupct}%" >&2
  }
  local sec=8; [ "$label" = debug ] && sec=8
  t health_c8 8 $sec GET /health "$TOKA"
  for c in 1 8 32; do t "overview_admin_5k_zones_c$c" $c $sec GET "/api/v1/overview?limit=0" "$TOKA"; done
  for c in 1 8 32; do t "overview_customer_c$c" $c $sec GET /api/v1/overview "$TOKU"; done
  t zones_list_admin_page20_c8 8 $sec GET "/api/v1/zones?limit=20" "$TOKA"
  t zones_list_customer_c8 8 $sec GET "/api/v1/zones" "$TOKU"
  for c in 1 8; do t "analytics_tenant_24h_c$c" $c $sec GET "/api/v1/analytics/tenant?range=24h" "$TOKU"; done
  t analytics_tenant_14d_c8 8 $sec GET "/api/v1/analytics/tenant?range=30d&interval=6h" "$TOKU"
  t analytics_global_14d_c8 8 $sec GET "/api/v1/analytics/global?range=30d&interval=6h" "$TOKA"
  t analytics_admin_all_tenants_24h_c8 8 $sec GET "/api/v1/analytics/tenant?range=24h" "$TOKA"
  t dns_lookup_c1 1 $sec POST /api/v1/dns/lookup "$TOKU" '{"domain":"www.lookup.test","record_type":"A"}'
  t dns_lookup_c8 8 $sec POST /api/v1/dns/lookup "$TOKU" '{"domain":"www.lookup.test","record_type":"A"}'
  echo "], \"rss_peak_kb\": $(hwm)}" >> "$OUT/results.json"
  stop_api
}
run_build release $APIR
# the debug build needs many minutes just to publish 5,000 zones at start-up; opt in with BENCH_DEBUG=1
[ -n "${BENCH_DEBUG:-}" ] && run_build debug $APID
echo '}' >> "$OUT/results.json"

# ---- query plans on the seeded database
ALICE=$(psqlq -c "select id from users where username='bench_alice'")
{ echo "== EXPLAIN (ANALYZE, BUFFERS): overview, admin (all zones, record counts via LATERAL)"
psqlq -c "EXPLAIN (ANALYZE, BUFFERS, TIMING OFF) SELECT CAST(z.id AS varchar), z.domain, z.status, CAST(z.tenant_id AS varchar), COALESCE(c.n, 0) FROM zones z LEFT JOIN LATERAL (SELECT sum(cnt)::bigint AS n FROM (SELECT record_type, count(*) AS cnt FROM records r WHERE r.zone_id = z.id GROUP BY record_type) t) c ON true ORDER BY z.domain"
echo; echo "== overview, customer (indexed visibility predicate)"
psqlq -c "EXPLAIN (ANALYZE, BUFFERS, TIMING OFF) SELECT CAST(z.id AS varchar), z.domain, COALESCE(c.n,0) FROM zones z LEFT JOIN LATERAL (SELECT sum(cnt)::bigint AS n FROM (SELECT record_type, count(*) AS cnt FROM records r WHERE r.zone_id = z.id GROUP BY record_type) t) c ON true WHERE (false OR z.id IN (SELECT id FROM zones WHERE owner = '$ALICE'::uuid UNION SELECT zone_id FROM zone_members WHERE user_id = '$ALICE'::uuid UNION SELECT id FROM zones WHERE tenant_id IN (SELECT tenant_id FROM tenant_members WHERE user_id = '$ALICE'::uuid))) ORDER BY z.domain"
echo; echo "== analytics: tenant series, 24h, 15-minute buckets"
psqlq -c "EXPLAIN (ANALYZE, BUFFERS, TIMING OFF) SELECT floor(extract(epoch from ts) / 900.0) * 900.0, sum(queries)::bigint, sum(failed)::bigint FROM zone_query_samples WHERE ts >= now() - interval '24 hours' AND tenant_id = (SELECT tenant_id FROM zones WHERE domain='bench-alice-1.example') GROUP BY 1 ORDER BY 1"
echo; echo "== analytics: record-type breakdown, tenant, 30 days"
psqlq -c "EXPLAIN (ANALYZE, BUFFERS, TIMING OFF) SELECT qtype, sum(queries)::bigint FROM zone_qtype_samples WHERE ts >= now() - interval '30 days' AND tenant_id = (SELECT tenant_id FROM zones WHERE domain='bench-alice-1.example') GROUP BY qtype ORDER BY 2 DESC"
echo; echo "== analytics: global series 30 days"
psqlq -c "EXPLAIN (ANALYZE, BUFFERS, TIMING OFF) SELECT floor(extract(epoch from ts) / 21600.0) * 21600.0, sum(requests)::bigint FROM analytics_samples WHERE ts >= now() - interval '30 days' GROUP BY 1 ORDER BY 1"
echo; echo "== shared rate limiter upsert"
psqlq -c "EXPLAIN (ANALYZE, BUFFERS, TIMING OFF) INSERT INTO shared_rate_limits (bucket, window_start, hits) VALUES ('lookup:x', to_timestamp(floor(extract(epoch from now())/60.0)*60.0), 1) ON CONFLICT (bucket, window_start) DO UPDATE SET hits = shared_rate_limits.hits + 1 RETURNING hits"; } > "$OUT/plans.txt" 2>&1
echo "done -> $OUT"
